<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function relp($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan_site($root){global $TEXT;$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=relp($f->getPathname(),$root);if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;elseif($f->isFile())$files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}sort($dirs);ksort($files);$refs=[];$rx=['/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i','/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];foreach($files as $p=>$m){if(!$m['text']||$m['size']>700000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}return ['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan_site($ROOT);if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}if(isset($_GET['data'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($D,JSON_UNESCAPED_SLASHES);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#060b10;color:#dce9ee;font-family:Inter,system-ui,Segoe UI,Arial}body{background:radial-gradient(circle at 50% 45%,#102029 0,#071016 46%,#04080c 100%)}#map{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:10;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.brand{font-size:19px;font-weight:800;letter-spacing:-.3px}.brand b{color:#59e2d1}.sub{margin-top:4px;color:#5e7680;font:8px ui-monospace;letter-spacing:1.4px}.stats{display:flex;gap:6px}.stat,.search,.panel,.button{background:#09151ce8;border:1px solid #7295a41f;border-radius:9px;backdrop-filter:blur(14px)}.stat{padding:7px 10px}.stat small{display:block;color:#526b75;font:7px ui-monospace}.stat strong{font:11px ui-monospace}.live{color:#59e4b5}.search{position:fixed;z-index:11;left:22px;top:78px;width:250px;padding:10px 12px;color:#eaffff;outline:0;font:9px ui-monospace}.panel{display:none;position:fixed;z-index:12;right:22px;top:78px;width:315px;padding:15px}.panel.show{display:block}.close{float:right;border:0;background:none;color:#70868e;font-size:18px;cursor:pointer}.eyebrow{color:#58737d;font:7px ui-monospace;letter-spacing:1.5px}.panel h2{font-size:15px;margin:7px 0 3px}.path{color:#61ddd1;font:8px ui-monospace;word-break:break-all}.relations{margin-top:11px;color:#79919a;font:8px ui-monospace;line-height:1.8;max-height:290px;overflow:auto}.relations b{color:#c8d9de}.bottom{position:fixed;z-index:11;left:22px;bottom:19px;display:flex;gap:6px}.button{padding:8px 11px;color:#9db4bd;font:800 8px ui-monospace;cursor:pointer}.button:hover{color:#eaffff;border-color:#59e2d155}.status{position:fixed;z-index:11;right:22px;bottom:22px;color:#607983;font:8px ui-monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#59e4b5;box-shadow:0 0 11px #59e4b5;margin-right:6px}.load{position:fixed;z-index:30;inset:0;display:grid;place-items:center;background:#04090df5}.loader{text-align:center}.loader b{display:block;font-size:10px}.loader small{display:block;color:#5b747d;font:8px ui-monospace;margin-top:5px}@media(max-width:700px){.top{left:11px;right:11px}.brand{font-size:16px}.sub{display:none}.stats .stat:nth-child(n+3){display:none}.search{left:11px;top:66px;width:195px}.panel{left:11px;right:11px;top:66px;width:auto}.bottom{left:11px;bottom:11px}.status{right:11px;bottom:49px}}
</style></head><body><div class="load" id="load"><div class="loader"><b>SmartToolz Relationship Manager</b><small>Organising live server relationships…</small></div></div><div class="top"><div><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="sub">ACTUAL FILES • ACTUAL REFERENCES • LIVE SERVER</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="files">0</strong></div><div class="stat"><small>RELATIONS</small><strong id="rels">0</strong></div><div class="stat"><small>SERVER</small><strong class="live" id="state">LIVE</strong></div></div></div><input id="search" class="search" placeholder="Search a file or folder…"><svg id="map" xmlns="http://www.w3.org/2000/svg"></svg><div id="panel" class="panel"><button id="close" class="close">×</button><div class="eyebrow">RELATIONSHIP DETAILS</div><h2 id="name"></h2><div id="path" class="path"></div><div id="relations" class="relations"></div></div><div class="bottom"><button class="button" id="center">CENTER</button><button class="button" id="refresh">RESCAN</button></div><div class="status"><span class="led"></span>SERVER <b id="hb">CONNECTING</b></div><script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>;const svg=document.getElementById('map');let W=innerWidth,H=innerHeight,zoom=.9,panX=0,panY=0,nodes=[],edges=[],selected=null,hover=null,drag=false,lx=0,ly=0;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function build(){const by=new Map;nodes=[];const roots=new Set();D.files.forEach(f=>roots.add(f.split('/')[0]));D.dirs.forEach(d=>roots.add(d.split('/')[0]));[...roots].sort().forEach(r=>nodes.push({id:'r:'+r,path:r,name:r+'/',folder:'root'}));D.dirs.filter(d=>d.split('/').length>1).forEach(d=>nodes.push({id:'d:'+d,path:d,name:d.split('/').pop()+'/',folder:'dir'}));D.files.forEach(f=>nodes.push({id:'f:'+f,path:f,name:f.split('/').pop(),folder:'file'}));nodes.forEach(n=>by.set(n.id,n));edges=[];for(const n of nodes){if(n.folder==='root')continue;const parts=n.path.split('/');const parent=parts.slice(0,-1).join('/');const pid=parts.length===1?'r:'+parts[0]:'d:'+parent;if(by.has(pid))edges.push({a:by.get(pid),b:n,type:'tree'})}for(const r of D.refs){const a=by.get('f:'+r.from),b=by.get('f:'+r.to);if(a&&b)edges.push({a,b,type:'dep'})}document.getElementById('files').textContent=D.files.length;document.getElementById('rels').textContent=D.refs.length;document.getElementById('load').style.display='none';draw()}
function layout(){const roots=nodes.filter(n=>n.folder==='root'),cols=Math.max(1,Math.ceil(Math.sqrt(roots.length))),gapX=Math.min(390,Math.max(270,(W-430)/Math.max(1,cols))),gapY=220,startX=W/2-(cols-1)*gapX/2,startY=H/2-Math.ceil(roots.length/cols)*105;roots.forEach((r,i)=>{const col=i%cols,row=Math.floor(i/cols);r.x=startX+col*gapX;r.y=startY+row*210});roots.forEach(r=>{const dirs=nodes.filter(n=>n.folder==='dir'&&n.path.startsWith(r.path+'/')&&!n.path.slice(r.path.length+1).includes('/'));const files=nodes.filter(n=>n.folder==='file'&&n.path.startsWith(r.path+'/')&&!n.path.slice(r.path.length+1).includes('/'));let y=r.y+40;dirs.forEach((d,i)=>{d.x=r.x-105;d.y=y+i*44});files.forEach((f,i)=>{f.x=r.x+75+(i%2)*100;f.y=y+Math.floor(i/2)*34});const deeper=nodes.filter(n=>n.folder==='dir'&&n.path.startsWith(r.path+'/')&&n.path.slice(r.path.length+1).includes('/'));deeper.forEach((d,i)=>{const parent=d.path.split('/').slice(0,-1).join('/');const p=nodes.find(n=>n.path===parent);d.x=(p?.x||r.x)+105;d.y=(p?.y||r.y)+44+i*30});const all=nodes.filter(n=>n.folder==='file'&&n.path.startsWith(r.path+'/')&&n.path.split('/').length>2);all.forEach((f,i)=>{const parent=f.path.split('/').slice(0,-1).join('/');const p=nodes.find(n=>n.path===parent);f.x=(p?.x||r.x)+80+(i%2)*90;f.y=(p?.y||r.y)+35+Math.floor(i/2)*29})});nodes.filter(n=>n.folder==='root'&&n.x<190).forEach(n=>n.x+=170)}
function P(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}function curve(a,b){const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,k=Math.min(65,d*.12);return{x:(a.x+b.x)/2-dy/d*k,y:(a.y+b.y)/2+dx/d*k}}
function connected(n){return selected&&(selected===n||edges.some(e=>(e.a===selected&&e.b===n)||(e.b===selected&&e.a===n)))}
function draw(){layout();svg.innerHTML='';const edgeLayer=document.createElementNS('http://www.w3.org/2000/svg','g');const nodeLayer=document.createElementNS('http://www.w3.org/2000/svg','g');for(const e of edges){const a=P(e.a),b=P(e.b),m=curve(a,b),on=connected(e.a)||connected(e.b)||hover&&(e.a===hover||e.b===hover);const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${a.x},${a.y} Q${m.x},${m.y} ${b.x},${b.y}`);path.setAttribute('fill','none');path.setAttribute('stroke',on?'#58dfcf':e.type==='dep'?'#37666e':'#26373f');path.setAttribute('stroke-width',on?'2':e.type==='dep'?'1.2':'.7');path.setAttribute('stroke-linecap','round');path.style.opacity=on?'0.95':e.type==='dep'?'.42':'.18';if(on&&e.type==='dep'){path.setAttribute('stroke-dasharray','5 9');path.style.animation='flow 1.3s linear infinite'}edgeLayer.appendChild(path)}for(const n of nodes){const p=P(n),on=n===selected||n===hover||connected(n);let w=n.folder==='root'?150:n.folder==='dir'?125:105,h=n.folder==='root'?38:n.folder==='dir'?28:24;const g=document.createElementNS('http://www.w3.org/2000/svg','g');const r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('x',p.x-w/2);r.setAttribute('y',p.y-h/2);r.setAttribute('width',w);r.setAttribute('height',h);r.setAttribute('rx',n.folder==='root'?11:7);r.setAttribute('fill',n.folder==='root'?'#0c2227':n.folder==='dir'?'#17172a':'#0b151b');r.setAttribute('stroke',on?'#58dfcf':n.folder==='root'?'#3d8d87':n.folder==='dir'?'#6456a0':'#29434c');r.setAttribute('stroke-width',on?'1.7':'1');r.style.filter=on?'drop-shadow(0 0 8px rgba(88,223,207,.28))':'none';g.appendChild(r);const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+3);t.setAttribute('text-anchor','middle');t.setAttribute('fill',on?'#eaffff':n.folder==='root'?'#7ce5da':'#80969f');t.setAttribute('font-size',n.folder==='root'?'10':n.folder==='dir'?'8.5':'8');t.setAttribute('font-family','ui-monospace,monospace');t.textContent=n.folder==='root'?'▣ '+n.name:n.name;g.appendChild(t);g.addEventListener('click',ev=>{ev.stopPropagation();select(n)});nodeLayer.appendChild(g)}svg.appendChild(edgeLayer);svg.appendChild(nodeLayer)}
function select(n){selected=n;document.getElementById('panel').classList.toggle('show',!!n);if(!n){draw();return}document.getElementById('name').textContent=n.name;document.getElementById('path').textContent=n.path;const links=edges.filter(e=>e.a===n||e.b===n).map(e=>e.a===n?e.b:e.a);document.getElementById('relations').innerHTML='<b>'+links.length+' connected items</b><br>'+links.slice(0,100).map(v=>'↳ '+esc(v.path)).join('<br>');draw()}
svg.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;svg.classList.add('drag')});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lx;panY+=e.clientY-ly;lx=e.clientX;ly=e.clientY;draw()}else{let best=null,bd=22;for(const n of nodes){const p=P(n),d=Math.hypot(e.clientX-p.x,e.clientY-p.y);if(d<bd){bd=d;best=n}}if(best!==hover){hover=best;draw()}}});addEventListener('pointerup',()=>{drag=false;svg.classList.remove('drag')});svg.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.35,Math.min(2.5,zoom*(e.deltaY<0?1.1:.9)));panX=e.clientX-(e.clientX-panX)*(zoom/old);panY=e.clientY-(e.clientY-panY)*(zoom/old);draw()},{passive:false});svg.addEventListener('click',()=>select(null));document.getElementById('close').onclick=()=>select(null);document.getElementById('center').onclick=()=>{zoom=.9;panX=0;panY=0;draw()};document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();const n=q?nodes.find(v=>v.path.toLowerCase().includes(q)):null;if(n){select(n);const p=P(n);panX+=W/2-p.x;panY+=H/2-p.y;draw()}else if(!q)select(null)};
async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'});const d=await r.json();document.getElementById('hb').textContent=d.time;document.getElementById('state').textContent='LIVE'}catch(e){document.getElementById('hb').textContent='OFFLINE';document.getElementById('state').textContent='OFFLINE'}}
addEventListener('resize',()=>{W=innerWidth;H=innerHeight;draw()});build();heartbeat();setInterval(heartbeat,2000);
</script><style>@keyframes flow{to{stroke-dashoffset:-28px}}</style></body></html>